from collections import deque, defaultdict
rev = defaultdict(list)
for c, evs in {'A': ['ev1'], 'B': ['A'], 'C': ['ev3']}.items():
    for e in evs: rev[e].append(c)
stale, q = set(), deque(['ev1'])
while q:
    n = q.popleft()
    for m in rev[n]:
        if m not in stale: stale.add(m); q.append(m)
print('invalidated conclusions:', sorted(stale), '| concl-C untouched')

